import Foundation
import Testing
@testable import LumaCore

/// The Swift port must give the same answers as Luma for Windows/Linux. The vectors file is
/// generated by the TypeScript implementation and replayed by both test suites.
struct ScheduleSyncTests {
    static let vectorsURL = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        .appending(path: "desktop/src/test/fixtures/schedule-sync-vectors.json")

    struct Vectors: Decodable {
        struct B32: Decodable { var hex: String; var b32: String }
        struct Pin: Decodable { var derHex: String; var pin: String }
        struct Pairing: Decodable { var code: String; var valid: Bool; var host: String?; var port: Int? }
        struct Expect: Decodable, Equatable { var status: String; var rev: Int? }
        struct Step: Decodable { var client: ScheduleSync.Peer; var ops: [ScheduleSync.Op]; var expect: [Expect] }
        struct Final: Decodable { var rev: Int; var deleted: Bool }
        struct Hub: Decodable { var hubID: String; var steps: [Step]; var finalSeq: Int; var final: [String: Final] }
        var base32: [B32]; var certPin: Pin; var pairing: [Pairing]; var hub: Hub
    }

    static func hex(_ s: String) -> Data { Data(stride(from: 0, to: s.count, by: 2).map { UInt8(s.dropFirst($0).prefix(2), radix: 16)! }) }

    @Test func sharedVectorsReplayIdentically() throws {
        let v = try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: Self.vectorsURL))
        for b in v.base32 { #expect(ScheduleSync.base32(Self.hex(b.hex)) == b.b32) }
        #expect(ScheduleSync.certPin(Self.hex(v.certPin.derHex)) == v.certPin.pin)
        for p in v.pairing {
            if p.valid {
                let code = try ScheduleSync.PairingCode(parsing: p.code)
                #expect(code.host == p.host); #expect(Int(code.port) == p.port)
            } else { #expect(throws: (any Error).self) { try ScheduleSync.PairingCode(parsing: p.code) } }
        }
        var doc = ScheduleSync.HubDoc(hubID: v.hub.hubID)
        for step in v.hub.steps {
            let body = try JSONEncoder().encode(ScheduleSync.Request(protocol: 1, client: step.client, hubID: nil, since: 0, ops: step.ops))
            let (next, response) = try ScheduleSync.handle(doc, body: body, hub: .init(id: doc.hubID, name: "Hub", platform: "macos"), timeZone: "UTC", now: 1)
            doc = next
            #expect(response.results.map { Vectors.Expect(status: $0.status.rawValue, rev: $0.rev) } == step.expect)
        }
        #expect(doc.seq == v.hub.finalSeq)
        for (key, want) in v.hub.final {
            #expect(doc.records[key]?.rev == want.rev)
            #expect((doc.records[key]?.deleted ?? false) == want.deleted)
        }
    }

    static let scene = ScheduleSync.SceneValue(id: "A1A1A1A1-0000-4000-8000-000000000001", name: "Evening", symbol: "moon.stars", icon: "moon",
                                               steps: [.init(id: "C3C3C3C3-0000-4000-8000-000000000003", deviceID: "AA:BB", command: .power(true), delayMilliseconds: 0)])
    static func schedule(_ change: (inout ScheduleSync.ScheduleValue) -> Void = { _ in }) -> ScheduleSync.ScheduleValue {
        var s = ScheduleSync.ScheduleValue(id: "B2B2B2B2-0000-4000-8000-000000000002", sceneID: scene.id, hour: 7, minute: 0, weekdays: Array(1...7), enabled: true, pausedUntil: nil)
        change(&s); return s
    }
    /// Sends a device's pending changes to an in-memory runner, as the app does over HTTPS.
    static func sync(_ state: inout ScheduleSync.ClientState, _ doc: inout ScheduleSync.HubDoc, id: String) throws -> [(kind: ScheduleSync.Kind, id: String, status: ScheduleSync.Status, reason: String)] {
        var refused: [(kind: ScheduleSync.Kind, id: String, status: ScheduleSync.Status, reason: String)] = []
        for batch in state.batches() {
            let body = try JSONEncoder().encode(ScheduleSync.Request(protocol: 1, client: .init(id: id, name: "Device", platform: "ios"), hubID: state.hubID, since: state.cursor, ops: batch))
            let (next, response) = try ScheduleSync.handle(doc, body: body, hub: .init(id: doc.hubID, name: "Mac", platform: "macos"), timeZone: "UTC", now: 1)
            doc = next
            // Round-trip through JSON like the wire.
            let wire = try JSONDecoder().decode(ScheduleSync.Response.self, from: JSONEncoder().encode(response))
            refused += try state.apply(wire, sent: batch)
        }
        return refused
    }

    @Test func offlineDeviceCannotResurrectOrReEnable() throws {
        var doc = ScheduleSync.HubDoc()
        var phone = ScheduleSync.ClientState(), ipad = ScheduleSync.ClientState()
        try phone.stage(.scene, id: Self.scene.id, desired: .scene(Self.scene))
        try phone.stage(.schedule, id: Self.schedule().id, desired: .schedule(Self.schedule()))
        #expect(try Self.sync(&phone, &doc, id: "D4D4D4D4-0000-4000-8000-000000000004").isEmpty)
        _ = try Self.sync(&ipad, &doc, id: "F6F6F6F6-0000-4000-8000-000000000006")
        // Phone disables (a reduce: always applies). iPad, offline, edits the time and re-enables.
        try phone.stage(.schedule, id: Self.schedule().id, desired: .schedule(Self.schedule { $0.enabled = false }))
        #expect(phone.batches().first?.first.map { if case .reduce = $0 { true } else { false } } == true)
        _ = try Self.sync(&phone, &doc, id: "D4D4D4D4-0000-4000-8000-000000000004")
        try ipad.stage(.schedule, id: Self.schedule().id, desired: .schedule(Self.schedule { $0.hour = 9 }))
        let refused = try Self.sync(&ipad, &doc, id: "F6F6F6F6-0000-4000-8000-000000000006")
        #expect(refused.map(\.status) == [.conflict])
        #expect(ipad.schedules.first?.enabled == false)
        // Phone deletes; the iPad's old edit can't bring it back.
        try phone.stage(.schedule, id: Self.schedule().id, desired: nil)
        _ = try Self.sync(&phone, &doc, id: "D4D4D4D4-0000-4000-8000-000000000004")
        try ipad.stage(.schedule, id: Self.schedule().id, desired: .schedule(Self.schedule { $0.minute = 30 }))
        _ = try Self.sync(&ipad, &doc, id: "F6F6F6F6-0000-4000-8000-000000000006")
        #expect(ipad.schedules.isEmpty)
        #expect(ScheduleSync.liveSchedules(doc.records).isEmpty)
    }

    @Test func pauseIsAReduceAndResumeNeedsTheCurrentRevision() {
        let base = Self.schedule()
        #expect(ScheduleSync.onlyReduces(base, Self.schedule { $0.pausedUntil = 5 }))
        #expect(ScheduleSync.onlyReduces(base, Self.schedule { $0.enabled = false }))
        #expect(!ScheduleSync.onlyReduces(Self.schedule { $0.pausedUntil = 5 }, base), "resume is a full edit")
        #expect(!ScheduleSync.onlyReduces(base, Self.schedule { $0.enabled = false; $0.hour = 8 }))
    }

    @Test func dstSkipsMissingTimeAndRunsRepeatedTimeOnce() throws {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = try #require(TimeZone(identifier: "America/New_York"))
        let iso = ISO8601DateFormatter()
        // 2026-03-08 02:30 doesn't exist in New York.
        let spring = Self.schedule { $0.hour = 2; $0.minute = 30 }
        #expect(ScheduleSync.occurrences(spring, lastTick: iso.date(from: "2026-03-08T05:00:00Z")!, now: iso.date(from: "2026-03-08T09:00:00Z")!, calendar: calendar).isEmpty)
        // 2026-11-01 01:30 happens twice; both share one key.
        let fall = Self.schedule { $0.hour = 1; $0.minute = 30 }
        let occ = ScheduleSync.occurrences(fall, lastTick: iso.date(from: "2026-11-01T04:00:00Z")!, now: iso.date(from: "2026-11-01T08:00:00Z")!, calendar: calendar)
        #expect(occ.count == 2)
        #expect(Set(occ.map(\.key)).count == 1)
    }

    @Test func requestsOverTheBodyLimitAreSplit() throws {
        var state = ScheduleSync.ClientState()
        for i in 0..<6 {
            let steps = (0..<200).map { j in ScheduleSync.Step(id: UUID().uuidString, deviceID: "AA:BB:CC:DD:EE:01", command: .rgb(j), delayMilliseconds: 10) }
            let id = UUID().uuidString
            try state.stage(.scene, id: id, desired: .scene(.init(id: id, name: "Big \(i)", symbol: "sparkles", icon: nil, steps: steps)))
        }
        let batches = state.batches()
        #expect(batches.count > 1)
        for batch in batches { #expect(try JSONEncoder().encode(batch).count < 64 * 1024) }
    }

    @Test func malformedRequestsAndForeignRunnersAreRefused() throws {
        let doc = ScheduleSync.HubDoc()
        #expect(throws: ScheduleSync.SyncError.self) { try ScheduleSync.handle(doc, body: Data(#"{"protocol":2}"#.utf8), hub: .init(id: doc.hubID, name: "Mac", platform: "macos"), timeZone: "UTC", now: 0) }
        let body = try JSONEncoder().encode(ScheduleSync.Request(protocol: 1, client: .init(id: UUID().uuidString, name: "x", platform: "ios"), hubID: UUID().uuidString, since: 0, ops: []))
        #expect(throws: ScheduleSync.SyncError.http(409, "This is a different runner than the one you paired with. Pair again.")) {
            try ScheduleSync.handle(doc, body: body, hub: .init(id: doc.hubID, name: "Mac", platform: "macos"), timeZone: "UTC", now: 0)
        }
    }

    /// Opt-in live check against a Windows/Linux runner over real TLS:
    /// LUMA_SYNC_INTEROP_CODE='luma1/…' swift test --filter liveElectronRunner
    @Test func liveElectronRunner() async throws {
        guard let code = ProcessInfo.processInfo.environment["LUMA_SYNC_INTEROP_CODE"] else { return }
        let target = try ScheduleSync.PairingCode(parsing: code)
        var state = ScheduleSync.ClientState()
        let client = ScheduleSync.Peer(id: UUID().uuidString, name: "Swift interop", platform: "ios")
        func send() async throws -> [(kind: ScheduleSync.Kind, id: String, status: ScheduleSync.Status, reason: String)] {
            var refused: [(kind: ScheduleSync.Kind, id: String, status: ScheduleSync.Status, reason: String)] = []
            for batch in state.batches() {
                let body = try JSONEncoder().encode(ScheduleSync.Request(protocol: 1, client: client, hubID: state.hubID, since: state.cursor, ops: batch))
                let r = try await ScheduleSyncTransport.send(target, path: ScheduleSync.syncPath, body: body)
                #expect(r.status == 200, "\(String(decoding: r.body, as: UTF8.self))")
                refused += try state.apply(JSONDecoder().decode(ScheduleSync.Response.self, from: r.body), sent: batch)
            }
            return refused
        }
        _ = try await send()
        let schedule = try #require(state.schedules.first, "the runner should have at least one schedule")
        var paused = schedule; paused.pausedUntil = Int64(Date().addingTimeInterval(3600).timeIntervalSince1970 * 1000)
        try state.stage(.schedule, id: schedule.id, desired: .schedule(paused))
        #expect(try await send().isEmpty)
        #expect(state.schedules.first { $0.id == schedule.id }?.pausedUntil == paused.pausedUntil)
        var wrong = target; wrong.token = String(repeating: "B", count: 26)
        let denied = try await ScheduleSyncTransport.send(wrong, path: ScheduleSync.syncPath, body: Data("{}".utf8))
        #expect(denied.status == 401)
        var badPin = target; badPin.pin = String(repeating: "A", count: 26)
        await #expect(throws: ScheduleSync.SyncError.self) { _ = try await ScheduleSyncTransport.send(badPin, path: ScheduleSync.syncPath, body: Data("{}".utf8)) }
    }
}
